// ATLAS database schema (Drizzle + SQLite). Claude Code-owned; see .claude/rules/database.md.
//
// Conventions
//  - Primary keys: UUID v4 text generated by the app.
//  - Timestamps: integer epoch milliseconds (UTC).
//  - Weights: kilograms (REAL), converted only at the display/input edge.
//  - Booleans: integer 0/1.
//  - History is snapshotted: session_exercises copies name/tracking type and
//    workout_sets copies the planned targets, so completed sessions never change
//    when routines or exercises are edited or removed. Muscle attribution for volume
//    analytics is intentionally live (exercise_muscles); see docs/DECISIONS.md DEC-012.
import { sql } from 'drizzle-orm';
import {
  check,
  index,
  integer,
  primaryKey,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core';

import {
  MUSCLE_ROLES,
  SESSION_STATUSES,
  SET_TYPES,
  TRACKING_TYPES,
} from '../types/enums';

const inList = (column: string, values: readonly string[]) =>
  sql.raw(`${column} IN (${values.map((v) => `'${v}'`).join(', ')})`);

// ---------------------------------------------------------------- exercises

export const exercises = sqliteTable(
  'exercises',
  {
    id: text('id').primaryKey(),
    // Stable identity of a built-in catalog exercise (NULL for custom) for idempotent seeding.
    builtinKey: text('builtin_key'),
    name: text('name').notNull(),
    equipment: text('equipment'),
    trackingType: text('tracking_type', { enum: TRACKING_TYPES }).notNull().default('weight_reps'),
    isCustom: integer('is_custom', { mode: 'boolean' }).notNull().default(false),
    isArchived: integer('is_archived', { mode: 'boolean' }).notNull().default(false),
    notes: text('notes'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [
    check('exercises_name_not_blank', sql`length(trim(${t.name})) > 0`),
    check('exercises_tracking_type_valid', inList('tracking_type', TRACKING_TYPES)),
    uniqueIndex('exercises_builtin_key_uq').on(t.builtinKey),
  ],
);

export const exerciseMuscles = sqliteTable(
  'exercise_muscles',
  {
    exerciseId: text('exercise_id')
      .notNull()
      .references(() => exercises.id, { onDelete: 'cascade' }),
    muscle: text('muscle').notNull(),
    role: text('role', { enum: MUSCLE_ROLES }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.exerciseId, t.muscle] }),
    check('exercise_muscles_role_valid', inList('role', MUSCLE_ROLES)),
    index('exercise_muscles_muscle_idx').on(t.muscle),
  ],
);

// ----------------------------------------------------------------- routines

export const routines = sqliteTable(
  'routines',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    notes: text('notes'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [check('routines_name_not_blank', sql`length(trim(${t.name})) > 0`)],
);

export const routineExercises = sqliteTable(
  'routine_exercises',
  {
    id: text('id').primaryKey(),
    routineId: text('routine_id')
      .notNull()
      .references(() => routines.id, { onDelete: 'cascade' }),
    // Exercises are archived, never hard-deleted while a routine uses them.
    exerciseId: text('exercise_id')
      .notNull()
      .references(() => exercises.id, { onDelete: 'restrict' }),
    position: integer('position').notNull(),
    restSeconds: integer('rest_seconds'),
    notes: text('notes'),
  },
  (t) => [
    uniqueIndex('routine_exercises_position_uq').on(t.routineId, t.position),
    check('routine_exercises_position_nonneg', sql`${t.position} >= 0`),
    check('routine_exercises_rest_nonneg', sql`${t.restSeconds} IS NULL OR ${t.restSeconds} >= 0`),
    index('routine_exercises_exercise_idx').on(t.exerciseId),
  ],
);

export const routineSets = sqliteTable(
  'routine_sets',
  {
    id: text('id').primaryKey(),
    routineExerciseId: text('routine_exercise_id')
      .notNull()
      .references(() => routineExercises.id, { onDelete: 'cascade' }),
    position: integer('position').notNull(),
    setType: text('set_type', { enum: SET_TYPES }).notNull().default('normal'),
    targetReps: integer('target_reps'),
    targetWeightKg: real('target_weight_kg'),
    targetDurationSeconds: integer('target_duration_seconds'),
    targetDistanceM: real('target_distance_m'),
  },
  (t) => [
    uniqueIndex('routine_sets_position_uq').on(t.routineExerciseId, t.position),
    check('routine_sets_position_nonneg', sql`${t.position} >= 0`),
    check('routine_sets_type_valid', inList('set_type', SET_TYPES)),
    check('routine_sets_targets_nonneg', sql`(${t.targetReps} IS NULL OR ${t.targetReps} >= 0)
      AND (${t.targetWeightKg} IS NULL OR ${t.targetWeightKg} >= 0)
      AND (${t.targetDurationSeconds} IS NULL OR ${t.targetDurationSeconds} >= 0)
      AND (${t.targetDistanceM} IS NULL OR ${t.targetDistanceM} >= 0)`),
  ],
);

// ------------------------------------------------------------------ sessions

export const workoutSessions = sqliteTable(
  'workout_sessions',
  {
    id: text('id').primaryKey(),
    // Snapshot of the routine at start; the link is informational only.
    routineId: text('routine_id').references(() => routines.id, { onDelete: 'set null' }),
    name: text('name').notNull(),
    status: text('status', { enum: SESSION_STATUSES }).notNull().default('active'),
    startedAt: integer('started_at').notNull(),
    endedAt: integer('ended_at'),
    // Rest timer end (epoch ms) so a countdown survives backgrounding and process death.
    restTimerEndsAt: integer('rest_timer_ends_at'),
    notes: text('notes'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [
    // Exactly one active workout: at most one row may have status = 'active'.
    uniqueIndex('workout_sessions_one_active_uq').on(t.status).where(sql`${t.status} = 'active'`),
    check('workout_sessions_status_valid', inList('status', SESSION_STATUSES)),
    check(
      'workout_sessions_end_matches_status',
      sql`(${t.status} = 'active' AND ${t.endedAt} IS NULL)
        OR (${t.status} = 'completed' AND ${t.endedAt} IS NOT NULL AND ${t.endedAt} >= ${t.startedAt})`,
    ),
    index('workout_sessions_status_started_idx').on(t.status, t.startedAt),
    index('workout_sessions_routine_idx').on(t.routineId),
  ],
);

export const sessionExercises = sqliteTable(
  'session_exercises',
  {
    id: text('id').primaryKey(),
    sessionId: text('session_id')
      .notNull()
      .references(() => workoutSessions.id, { onDelete: 'cascade' }),
    // Nullable: history survives exercise deletion. name/trackingType are snapshots.
    exerciseId: text('exercise_id').references(() => exercises.id, { onDelete: 'set null' }),
    name: text('name').notNull(),
    trackingType: text('tracking_type', { enum: TRACKING_TYPES }).notNull(),
    position: integer('position').notNull(),
    restSeconds: integer('rest_seconds'),
    notes: text('notes'),
  },
  (t) => [
    uniqueIndex('session_exercises_position_uq').on(t.sessionId, t.position),
    check('session_exercises_position_nonneg', sql`${t.position} >= 0`),
    check('session_exercises_tracking_type_valid', inList('tracking_type', TRACKING_TYPES)),
    check('session_exercises_rest_nonneg', sql`${t.restSeconds} IS NULL OR ${t.restSeconds} >= 0`),
    index('session_exercises_exercise_idx').on(t.exerciseId),
  ],
);

export const workoutSets = sqliteTable(
  'workout_sets',
  {
    id: text('id').primaryKey(),
    sessionExerciseId: text('session_exercise_id')
      .notNull()
      .references(() => sessionExercises.id, { onDelete: 'cascade' }),
    position: integer('position').notNull(),
    setType: text('set_type', { enum: SET_TYPES }).notNull().default('normal'),
    // Planned targets copied from the routine at session start (never read live).
    targetReps: integer('target_reps'),
    targetWeightKg: real('target_weight_kg'),
    targetDurationSeconds: integer('target_duration_seconds'),
    targetDistanceM: real('target_distance_m'),
    weightKg: real('weight_kg'),
    reps: integer('reps'),
    rpe: real('rpe'),
    durationSeconds: integer('duration_seconds'),
    distanceM: real('distance_m'),
    // Analytics count only is_completed = 1 sets of completed sessions.
    isCompleted: integer('is_completed', { mode: 'boolean' }).notNull().default(false),
    completedAt: integer('completed_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [
    uniqueIndex('workout_sets_position_uq').on(t.sessionExerciseId, t.position),
    check('workout_sets_position_nonneg', sql`${t.position} >= 0`),
    check('workout_sets_type_valid', inList('set_type', SET_TYPES)),
    check('workout_sets_values_valid', sql`(${t.weightKg} IS NULL OR ${t.weightKg} >= 0)
      AND (${t.reps} IS NULL OR ${t.reps} >= 0)
      AND (${t.rpe} IS NULL OR (${t.rpe} >= 1 AND ${t.rpe} <= 10))
      AND (${t.durationSeconds} IS NULL OR ${t.durationSeconds} >= 0)
      AND (${t.distanceM} IS NULL OR ${t.distanceM} >= 0)`),
    check('workout_sets_targets_nonneg', sql`(${t.targetReps} IS NULL OR ${t.targetReps} >= 0)
      AND (${t.targetWeightKg} IS NULL OR ${t.targetWeightKg} >= 0)
      AND (${t.targetDurationSeconds} IS NULL OR ${t.targetDurationSeconds} >= 0)
      AND (${t.targetDistanceM} IS NULL OR ${t.targetDistanceM} >= 0)`),
    check(
      'workout_sets_completed_matches_time',
      sql`(${t.isCompleted} = 1 AND ${t.completedAt} IS NOT NULL) OR (${t.isCompleted} = 0 AND ${t.completedAt} IS NULL)`,
    ),
  ],
);

// ------------------------------------------------------------------ settings

export const appSettings = sqliteTable('app_settings', {
  key: text('key').primaryKey(),
  // JSON-encoded; every read is parsed through a Zod schema with a default.
  value: text('value').notNull(),
  updatedAt: integer('updated_at').notNull(),
});

export const schema = {
  exercises,
  exerciseMuscles,
  routines,
  routineExercises,
  routineSets,
  workoutSessions,
  sessionExercises,
  workoutSets,
  appSettings,
};
